import {jest} from '@jest/globals';
import {WebSocket} from 'ws';
import {createMessageHandler} from './messageHandler.js';
import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import type {ChatSession} from '../../types/session.js';
import type {OutgoingMessage} from '../../types/messages.js';
import type {SessionStore} from '../../types/sessionStore.js';

describe('list_sessions handler dispatch', () => {
  it('lists the authenticated user sessions and serialises summary dates', async () => {
    const sent: OutgoingMessage[] = [];
    const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
    const summary = {
      sessionId: 's1',
      createdAt: new Date('2026-01-01T00:00:00.000Z'),
      updatedAt: new Date('2026-01-02T00:00:00.000Z'),
      entryCount: 2,
    };
    const listFor = jest.fn(() => [summary]);
    const sessionStore = {listFor} as unknown as SessionStore;
    const session: ChatSession = {sessionId: 'active', userId: 'u1', entries: []};

    await createMessageHandler({} as ChatOrchestrator, sessionStore)(ws, session, {
      type: 'list_sessions',
      limit: 10,
      userId: 'u2',
    });

    expect({calls: listFor.mock.calls, sent}).toEqual({
      calls: [['u1', {limit: 10, before: undefined}]],
      sent: [
        {
          type: 'session_list',
          sessions: [
            {
              sessionId: 's1',
              createdAt: '2026-01-01T00:00:00.000Z',
              updatedAt: '2026-01-02T00:00:00.000Z',
              entryCount: 2,
            },
          ],
        },
      ],
    });
  });
});
import {validateMessage} from './validation.js';

// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('accepts a bare list_sessions frame', () => {
    expect(validateMessage({type: 'list_sessions'})).toEqual({valid: true, data: {type: 'list_sessions'}});
  });

  it('accepts a list_sessions frame with its composite cursor', () => {
    expect(
      validateMessage({
        type: 'list_sessions',
        limit: 10,
        before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
      })
    ).toEqual({
      valid: true,
      data: {
        type: 'list_sessions',
        limit: 10,
        before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
      },
    });
  });

  it('rejects a page size above the protocol maximum', () => {
    expect(validateMessage({type: 'list_sessions', limit: 201})).toEqual({
      valid: false,
      error: 'list_sessions limit must be an integer between 1 and 200',
    });
  });
});
import http from 'http';
import {WebSocketServer} from 'ws';
import type {Express} from 'express';
import type {WsAuthenticator} from '../types/auth.js';
import type {SessionStore} from '../types/sessionStore.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
import type {ToolRegistry} from '../orchestration/tools/registry.js';
import {createUpgradeHandler, createConnectionHandler, ExtWebSocket} from './ws/connectionHandler.js';
import {createMessageHandler} from './ws/messageHandler.js';
import {selectSubprotocol} from './ws/subprotocol.js';
import type {ConnectInfo, SessionResumeOptions} from './ws/sessionResume.js';
import {log} from '../shared/logger.js';

export interface HalServerOptions {
  app: Express;
  wsAuth: WsAuthenticator;
  sessionStore: SessionStore;
  orchestrator: ChatOrchestrator;
  toolRegistry?: ToolRegistry;
  basePath?: string;
  port?: number;
  heartbeatIntervalMs?: number;
  onConnect?: (session: import('../types/session.js').ChatSession, connection: ConnectInfo) => void | Promise<void>;
  onDisconnect?: (sessionId: string) => void | Promise<void>;
  resume?: SessionResumeOptions;
}

export interface HalServer {
  server: http.Server;
  wss: WebSocketServer;
  start: (port?: number) => Promise<void>;
  stop: () => Promise<void>;
}

export function createServer(options: HalServerOptions): HalServer {
  const basePath = options.basePath ?? '/hal';

  const wss = new WebSocketServer({
    noServer: true,
    handleProtocols: selectSubprotocol,
  });

  const handleMessage = createMessageHandler(options.orchestrator, options.sessionStore);
  const examplePrompts = options.toolRegistry?.getExamplePrompts() ?? [];

  const deps = {
    wsAuth: options.wsAuth,
    sessionStore: options.sessionStore,
    handleMessage,
    basePath,
    onConnect: options.onConnect,
    onDisconnect: options.onDisconnect,
    resume: options.resume,
  };

  const handleUpgrade = createUpgradeHandler(wss, deps);
  const handleConnection = createConnectionHandler(deps, examplePrompts);

  const server = http.createServer(options.app);

  server.on('upgrade', (request, socket, head) => {
    handleUpgrade(request, socket, head);
  });

  wss.on('connection', ws => {
    handleConnection(ws as ExtWebSocket);
  });

